// 门店
export interface Store {
  id: string;
  name: string;
  code: string;
  address: string;
  region: string;
  manager: string;
  phone: string;
  openDate: string;
  avgScore: number;
}

// 巡检照片（mock 历史数据）
export interface Photo {
  id: string;
  inspectionId: string;
  category: PhotoCategory;
  url: string;
  aiResult: string;
  confidence: number;
  // 红框标注位置（百分比）
  box?: { x: number; y: number; w: number; h: number };
}

// 取证实体（用户新建巡检的取证记录，包含 Photo 的所有展示字段）
export interface Evidence {
  id: string;
  inspectionId: string;
  templateItemId: string;
  category: PhotoCategory;
  url: string;
  source: "demo" | "upload" | "camera";
  capturedAt: string;
  // AI 分析结果（由 AI 填充）
  aiResult: string;
  confidence: number;
  box?: { x: number; y: number; w: number; h: number };
}

export type PhotoCategory =
  | "食材标签"
  | "冰箱温度"
  | "操作台"
  | "台账记录"
  | "垃圾桶"
  | "消毒柜"
  | "仓储"
  | "洗手池"
  | "健康证";

// 巡检模板检查项
export interface TemplateItem {
  id: string; // 稳定 ID，用于关联 Evidence
  name: string;
  category: PhotoCategory;
  standard: string;
  photoReq: string;
  riskRule: string;
  regulation: string;
  // 结构化照片要求（校验用，photoReq 仅用于展示）
  requiredPhotoCount: number;
  maxPhotoCount: number;
  required: boolean;
}

// 巡检模板
export interface Template {
  id: string;
  name: string;
  type: "daily" | "standard" | "special";
  typeName: string;
  color: string;
  itemCount: number;
  description: string;
  items: TemplateItem[];
}

// 风险等级
export type RiskLevel = "high" | "mid" | "low";

// 风险状态
export type RiskStatus =
  | "ai_detected" // AI识别
  | "pending" // 待确认
  | "confirmed" // 已确认（待整改）
  | "fixing" // 整改中
  | "fixed" // 已整改
  | "verified"; // 已验证

// 风险项
export interface Risk {
  id: string;
  inspectionId: string;
  description: string;
  level: RiskLevel;
  basis: string; // 判定依据（法规/标准）
  confidence: number; // AI置信度
  suggestion: string; // 整改建议
  status: RiskStatus;
  photoId: string; // 主证据 ID（向后兼容，等于 primaryEvidenceId）
  category: PhotoCategory;
  // 关联的检查项和证据（一个风险对应一个检查项，可关联多张证据）
  templateItemId?: string;
  evidenceIds?: string[];
  primaryEvidenceId?: string;
  // 整改后照片
  fixedPhotoUrl?: string;
  fixNote?: string;
  fixedTime?: string;
  // 整改任务 ID（关联 RectificationTask）
  rectificationTaskId?: string;
}

// 整改任务：每个风险对应一个整改任务（轻量闭环）
export interface RectificationTask {
  id: string;
  riskId: string;
  // 责任人
  assignee: string;
  // 截止时间（YYYY-MM-DD）
  dueDate: string;
  // 开始整改时间
  startedAt?: string;
  // 提交整改说明
  fixNote?: string;
  // 整改后样本照片 URL
  fixedPhotoUrl?: string;
  // 提交整改时间
  submittedAt?: string;
  // 验证人
  verifier?: string;
  // 验证时间
  verifiedAt?: string;
  // 驳回原因
  rejectReason?: string;
  // 驳回时间
  rejectedAt?: string;
  // 驳回次数
  rejectCount: number;
}

// 审计事件：记录风险状态流转全过程
export interface AuditEvent {
  id: string;
  riskId: string;
  // 操作类型
  action:
    | "ai_detected" // AI 识别
    | "confirm" // 确认风险
    | "start_fix" // 开始整改
    | "submit_fix" // 提交整改
    | "verify" // 验证通过
    | "reject"; // 驳回整改
  // 操作人
  operator: string;
  // 操作时间（本地时间字符串）
  timestamp: string;
  // 备注（如驳回原因）
  note?: string;
}

// 巡检评级
export type Grade = "优" | "良" | "中" | "差";

// 巡检
export interface Inspection {
  id: string;
  storeId: string;
  templateId: string;
  templateName: string;
  inspector: string;
  inspectTime: string;
  score: number;
  grade: Grade;
  status: "completed" | "analyzing" | "draft";
  riskCount: number;
  highRiskCount: number;
  midRiskCount: number;
  lowRiskCount: number;
  photoCount: number;
  // 仅汇总记录：有统计数字但无风险明细和照片
  summaryOnly?: boolean;
}

// 趋势数据点
export interface TrendPoint {
  date: string;
  count: number;
}

// 风险类型分布
export interface RiskTypeData {
  name: string;
  value: number;
}

