// ============ 视觉强化组件 ============

// 得分环（升级版：渐变描边 + 光晕）
export function ScoreRing({ score, size = 80 }: { score: number; size?: number }) {
  const radius = (size - 12) / 2;
  const circumference = 2 * Math.PI * radius;
  const offset = circumference - (score / 100) * circumference;
  const colorMap =
    score >= 90
      ? { from: "#10b981", to: "#059669", text: "#047857" }
      : score >= 75
      ? { from: "#2563eb", to: "#06b6d4", text: "#1d4ed8" }
      : score >= 60
      ? { from: "#f59e0b", to: "#ea580c", text: "#c2410c" }
      : { from: "#dc2626", to: "#991b1b", text: "#b91c1c" };
  const grade = score >= 90 ? "优" : score >= 75 ? "良" : score >= 60 ? "中" : "差";
  const gradientId = `score-grad-${size}`;

  return (
    <div
      className="relative inline-flex items-center justify-center"
      style={{ width: size, height: size }}
    >
      <svg width={size} height={size} className="-rotate-90">
        <defs>
          <linearGradient id={gradientId} x1="0%" y1="0%" x2="100%" y2="100%">
            <stop offset="0%" stopColor={colorMap.from} />
            <stop offset="100%" stopColor={colorMap.to} />
          </linearGradient>
        </defs>
        <circle
          cx={size / 2}
          cy={size / 2}
          r={radius}
          fill="none"
          stroke="#e2e8f0"
          strokeWidth="6"
        />
        <circle
          cx={size / 2}
          cy={size / 2}
          r={radius}
          fill="none"
          stroke={`url(#${gradientId})`}
          strokeWidth="6"
          strokeDasharray={circumference}
          strokeDashoffset={offset}
          strokeLinecap="round"
          style={{
            transition: "stroke-dashoffset 1s cubic-bezier(0.4, 0, 0.2, 1)",
            filter: `drop-shadow(0 0 6px ${colorMap.from}40)`,
          }}
        />
      </svg>
      <div className="absolute inset-0 flex flex-col items-center justify-center">
        <span
          className="font-display font-bold tabular-nums leading-none"
          style={{ color: colorMap.text, fontSize: size * 0.32 }}
        >
          {score}
        </span>
        <span className="text-[10px] text-ink-400 font-medium mt-0.5">{grade}</span>
      </div>
    </div>
  );
}

// ============ 数字滚动动画 ============

export function CountUp({
  end,
  duration = 1200,
  suffix = "",
  prefix = "",
  decimals = 0,
  className,
}: {
  end: number;
  duration?: number;
  suffix?: string;
  prefix?: string;
  decimals?: number;
  className?: string;
}) {
  const [value, setValue] = useState(0);
  const [hasStarted, setHasStarted] = useState(false);
  const ref = useRef<HTMLSpanElement>(null);

  useEffect(() => {
    const observer = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting && !hasStarted) {
          setHasStarted(true);
          const startTime = Date.now();
          const tick = () => {
            const elapsed = Date.now() - startTime;
            const progress = Math.min(elapsed / duration, 1);
            // easeOutExpo 缓动
            const eased =
              progress === 1 ? 1 : 1 - Math.pow(2, -10 * progress);
            setValue(end * eased);
            if (progress < 1) requestAnimationFrame(tick);
            else setValue(end);
          };
          requestAnimationFrame(tick);
        }
      },
      { threshold: 0.1 }
    );
    if (ref.current) observer.observe(ref.current);
    return () => observer.disconnect();
  }, [end, duration, hasStarted]);

  return (
    <span ref={ref} className={cn("tabular-nums", className)}>
      {prefix}
      {value.toFixed(decimals)}
      {suffix}
    </span>
  );
}

// ============ 按钮 ============

export function Button({
  children,
  variant = "primary",
  size = "md",
  className,
  icon,
  loading,
  ...props
}: {
  children?: ReactNode;
  variant?: "primary" | "secondary" | "ghost" | "danger" | "gradient" | "outline";
  size?: "sm" | "md" | "lg";
  icon?: ReactNode;
  loading?: boolean;
} & React.ButtonHTMLAttributes<HTMLButtonElement>) {
  const variants = {
    primary:
      "bg-brand-900 text-white hover:bg-brand-800 shadow-sm hover:shadow-glow-brand hover:-translate-y-0.5",
    secondary:
      "bg-white text-brand-700 border border-brand-200/80 hover:bg-brand-50 hover:border-brand-300 hover:-translate-y-0.5",
    ghost: "text-ink-500 hover:bg-ink-100/80 hover:text-ink-800",
    danger:
      "bg-gradient-to-r from-red-600 to-red-500 text-white hover:shadow-glow-red hover:-translate-y-0.5",
    gradient:
      "bg-gradient-to-r from-brand-900 via-brand-700 to-cyan-600 text-white shadow-sm hover:shadow-glow-brand hover:-translate-y-0.5 bg-[length:200%_200%] hover:bg-[position:100%_0] transition-all duration-500",
    outline:
      "bg-transparent text-ink-700 border border-ink-200 hover:border-brand-300 hover:text-brand-700 hover:bg-brand-50/50",
  };
  const sizes = {
    sm: "px-3 py-1.5 text-xs gap-1 rounded-md",
    md: "px-4 py-2 text-sm gap-1.5 rounded-lg",
    lg: "px-6 py-2.5 text-sm gap-2 rounded-xl",
  };
  return (
    <button
      className={cn(
        "inline-flex items-center justify-center font-semibold transition-all duration-300 cursor-pointer active:scale-[0.97] disabled:opacity-50 disabled:cursor-not-allowed disabled:hover:translate-y-0",
        variants[variant],
        sizes[size],
        className
      )}
      disabled={loading || props.disabled}
      {...props}
    >
      {loading ? (
        <svg
          className="animate-spin w-4 h-4"
          viewBox="0 0 24 24"
          fill="none"
        >
          <circle
            className="opacity-25"
            cx="12"
            cy="12"
            r="10"
            stroke="currentColor"
            strokeWidth="4"
          />
          <path
            className="opacity-75"
            fill="currentColor"
            d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"
          />
        </svg>
      ) : (
        icon
      )}
      {children}
    </button>
  );
}

