    cyan: { bg: "from-cyan-500 to-cyan-600", text: "text-cyan-700", glow: "shadow-glow-cyan" },
    emerald: { bg: "from-emerald-500 to-emerald-600", text: "text-emerald-700", glow: "shadow-glow-cyan" },
    red: { bg: "from-red-500 to-red-600", text: "text-red-600", glow: "shadow-glow-red" },
