// ============ 交错动画容器 ============

export function AnimatedGroup({
  children,
  delay = 80,
  className,
}: {
  children: ReactNode;
  delay?: number;
  className?: string;
}) {
  const childrenArray = Array.isArray(children) ? children : [children];
  return (
    <div className={className}>
      {childrenArray.map((child, i) => (
        <div
          key={i}
          className="animate-stagger-in"
          style={{ animationDelay: `${i * delay}ms` }}
        >
          {child}
        </div>
      ))}
    </div>
  );
}

// ============ Tabs 组件 ============

export function Tabs({
  tabs,
  activeTab,
  onChange,
  variant = "default",
  className,
}: {
  tabs: { key: string; label: string; icon?: ReactNode }[];
  activeTab: string;
  onChange: (key: string) => void;
  variant?: "default" | "pills" | "underlined";
  className?: string;
}) {
  const baseStyles = {
    default: {
      container: "bg-ink-100/60 p-1 rounded-xl",
      tab: "px-4 py-2 rounded-lg text-xs font-medium transition-all cursor-pointer",
      active: "bg-white text-brand-700 shadow-sm",
      inactive: "text-ink-500 hover:text-ink-700 hover:bg-white/50",
    },
    pills: {
      container: "flex gap-2",
      tab: "px-3 py-1.5 rounded-full text-xs font-medium transition-all cursor-pointer border",
      active: "bg-gradient-to-r from-brand-900 to-brand-700 text-white border-transparent shadow-sm",
      inactive: "bg-white text-ink-500 border-ink-200 hover:border-brand-300 hover:text-brand-700",
    },
    underlined: {
      container: "flex gap-1 border-b border-ink-200",
      tab: "px-4 py-2.5 text-sm font-medium transition-all cursor-pointer relative",
      active: "text-brand-700",
      inactive: "text-ink-500 hover:text-ink-700",
    },
  };
  const styles = baseStyles[variant];

  return (
    <div className={cn(styles.container, className)}>
      {tabs.map((tab) => (
        <button
          key={tab.key}
          onClick={() => onChange(tab.key)}
          className={cn(
            styles.tab,
            "inline-flex items-center gap-1.5",
            activeTab === tab.key ? styles.active : styles.inactive
          )}
        >
          {tab.icon}
          {tab.label}
          {variant === "underlined" && activeTab === tab.key && (
            <span className="absolute bottom-0 left-0 right-0 h-0.5 bg-gradient-to-r from-brand-700 to-cyan-500 rounded-full" />
          )}
        </button>
      ))}
    </div>
  );
}

// ============ Tooltip 组件 ============

export function Tooltip({
  children,
  content,
  position = "top",
}: {
  children: ReactNode;
  content: ReactNode;
  position?: "top" | "bottom" | "left" | "right";
}) {
  const [show, setShow] = useState(false);
  const positionStyles = {
    top: "bottom-full left-1/2 -translate-x-1/2 mb-2",
    bottom: "top-full left-1/2 -translate-x-1/2 mt-2",
    left: "right-full top-1/2 -translate-y-1/2 mr-2",
    right: "left-full top-1/2 -translate-y-1/2 ml-2",
  };

  return (
    <div
      className="relative inline-flex"
      onMouseEnter={() => setShow(true)}
      onMouseLeave={() => setShow(false)}
    >
      {children}
      {show && (
        <div
          className={cn(
            "absolute z-50 px-2 py-1 text-xs text-white bg-ink-800 rounded-md shadow-lg whitespace-nowrap animate-zoom-in",
            positionStyles[position]
          )}
        >
          {content}
        </div>
      )}
    </div>
  );
}

