// ============ 进度条组件 ============

export function ProgressBar({
  value,
  max = 100,
  color = "brand",
  size = "md",
  showLabel = false,
  className,
}: {
  value: number;
  max?: number;
  color?: "brand" | "emerald" | "amber" | "red" | "cyan";
  size?: "sm" | "md" | "lg";
  showLabel?: boolean;
  className?: string;
}) {
  const pct = Math.min(100, Math.max(0, (value / max) * 100));
  const colors = {
    brand: "from-brand-700 to-brand-500",
    emerald: "from-emerald-500 to-emerald-400",
    amber: "from-amber-500 to-amber-400",
    red: "from-red-500 to-red-400",
    cyan: "from-cyan-500 to-cyan-400",
  };
  const heights = {
    sm: "h-1",
    md: "h-2",
    lg: "h-3",
  };
  return (
    <div className={cn("w-full", className)}>
      <div
        className={cn(
          "w-full bg-ink-100/60 rounded-full overflow-hidden",
          heights[size]
        )}
      >
        <div
          className={cn(
            "h-full bg-gradient-to-r rounded-full transition-all duration-700 ease-out relative",
            colors[color]
          )}
          style={{ width: `${pct}%` }}
        >
          <div className="absolute inset-0 bg-white/30 shine-bar" />
        </div>
      </div>
      {showLabel && (
        <div className="flex justify-between mt-1 text-[10px] text-ink-400">
          <span>{value}</span>
          <span>{max}</span>
        </div>
      )}
    </div>
  );
}

